choose.when:
(
SELECT TRAN_PR, TRAN_PHONE, TRAN_CALLBACK, TRAN_STATUS, REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), TRAN_DATE, 120), '-', ''), ':', ''), ' ', '') AS TRAN_DATE, TRAN_RSLT, TRAN_MSG, CORP_RESERVED2 FROM ${tableName} WHERE REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), TRAN_DATE, 120), '-', ''), ':', ''), ' ', '') >= #{startTime} AND REPLACE(REPLACE(REPLACE(CONVERT(VARCHAR(19), TRAN_DATE, 120), '-', ''), ':', ''), ' ', '') <= #{endTime}
AND TRAN_PHONE LIKE CONCAT('%', #{phoneNum}, '%')
) ORDER BY TRAN_DATE DESC
